insert into pajang_private.question_catalog(id,prompt,samples) values
  (5, '마음에 드는 사람과 나란히 탄 기차가 출발하면 어떤 창밖 풍경을 가리켜 줄까요?', array['손을 흔드는 사람들을 봐요.', '뒤로 미끄러지는 역 이름이요.', '건물이 논밭으로 바뀌는 순간이요.']),
  (11, '둘이 여행 지도를 펼친다면 어디에 먼저 동그라미를 칠까요?', array['색이 제일 짙은 숲이요.', '강 두 개가 만나는 다리요.', '이름이 재미있는 작은 역이요.']),
  (16, '한 우산 아래서 “여기 잠깐만 같이 봐요” 하고 싶은 풍경은요?', array['돌계단을 타고 흐르는 물이요.', '처마에 나란히 맺힌 빗방울이요.', '웅덩이에 거꾸로 비친 신호등이요.']),
  (24, '골목 데이트의 첫 갈림길, 내가 길잡이라면 어디로 상대를 데려갈까요?', array['화분이 많은 쪽으로 가요.', '언덕 너머가 궁금해서 올라가요.', '웃음소리가 들리는 쪽을 골라요.']),
  (30, '맨발로 바닷가에 선 두 사람, 어떤 놀이부터 제안하고 싶나요?', array['파도가 발에 닿을 때까지 서 있어요.', '모래에 발자국 두 줄을 남겨요.', '물기 없는 자리를 찾아 누워요.']),
  (34, '첫 반나절 여행에서 상대가 “그거 챙기길 잘했다” 할 만한 짐은요?', array['엉덩이만 한 작은 방석이요.', '날씨가 바뀔 때 걸칠 얇은 셔츠요.', '어디서든 낮잠 잘 수 있는 안대요.']),
