  (47, '둘이 걷다가 전망대 표지판을 보면 어떤 결정을 내릴까요?', array['계단 수부터 세어 보고 올라가요.', '돌아오는 길의 해 질 때를 노려요.', '아래에서 보는 풍경도 즐겨요.']),
  (52, '물가에서 말이 잠깐 끊겨도 어색하지 않게 해 줄 풍경이 있다면요?', array['오리들이 줄을 바꾸는 게 웃겨요.', '바람 따라 물 색이 달라져요.', '대화가 끊겨도 물소리가 이어져요.']),
  (56, '데이트 시간이 한 시간 늘었다면 계획에 없던 어떤 제안을 해 볼까요?', array['작은 배를 타고 강을 건너요.', '광장에 앉아 지나가는 개를 봐요.', '방금 지나친 전망 좋은 길로 돌아가요.']),
  (61, '함께 걷는 사람에게 여기를 보라고 가리키고 싶은 순간은요?', array['담장 위 고양이가 하품할 때요.', '건물 사이에 달이 딱 걸릴 때요.', '은행잎이 빙글빙글 돌며 떨어질 때요.']),
