  (77, '전망대 망원경의 초점을 내가 먼저 맞춰준다면 상대에게 뭘 보여줄까요?', array['산길이 끝나는 지점을 찾아요.', '항구로 들어오는 배를 따라가요.', '지붕 위 풍향계가 도는 걸 봐요.']),
  (83, '떠나기 전 서로가 기대하는 아침 풍경을 맞혀 본다면 내 정답은요?', array['해 뜨는 게 보이는 빈 들판이요.', '바람에 스치는 큰 나무 한 그루요.', '밤이면 불이 켜지는 옛 시계탑이요.']),
  (85, '둘이서 낯선 도시를 구경할 때 편하게 느끼는 속도는요?', array['한 골목을 두 번 걸을 정도요.', '한 바퀴 돌고 마음에 든 곳에 멈춰요.', '둘 중 천천히 걷는 사람에게 맞춰요.']),
  (91, '별자리를 모르는 두 사람이 별 보러 가면 어떤 식으로 즐길 수 있을까요?', array['별 서너 개를 이어 새 이름을 지어요.', '별똥별을 누가 먼저 보나 기다려요.', '돗자리를 펴고 가만히 올려다봐요.']),
  (98, '내가 고른 데이트 코스에서 길을 잃었다면 상대에게 뭐라고 말할까요?', array['이왕 온 김에 저 벽화 보고 갈까요?', '잠깐 앉아서 지도부터 펼쳐 볼까요?', '아까 본 노란 대문이 어디였죠?']),
  (105, '첫 만남에서 공원 벤치에 앉아 이야기한다면 어떤 자리를 고를까요?', array['커다란 나무 그늘 아래요.', '분수 물방울이 살짝 닿는 자리요.', '강아지들이 지나가는 길 앞이요.']),
  (112, '육교 위에서 언제 “여기서 잠깐 같이 보고 갈래요?” 하고 싶나요?', array['차 불빛이 길게 이어지는 저녁이요.', '눈 덮인 가로수가 한눈에 보일 때요.', '멀리 산마루에 해가 걸려 있을 때요.']),
  (118, '유적지 데이트에서 안내판을 읽고 상대한테 들려주고 싶은 이야기는요?', array['이름이 왜 이렇게 붙었는지요.', '옛날 사진이 어디서 찍혔는지요.', '이 강에 계절마다 오는 새 이름이요.']),
  (124, '바다에 간다면 해 뜰 때와 해 질 때 중 언제 함께 보고 싶나요?', array['수평선이 처음 분홍빛이 될 때요.', '오래 앉아 노을이 사라질 때까지요.', '같은 바다에서 둘 다 보고 싶어요.']),
  (130, '성곽길 데이트를 안내한다면 어느 지점에서 멈춰 구경시켜 줄까요?', array['돌 틈 사이로 풀이 자란 곳이요.', '성 밖 지붕이 한꺼번에 보이는 곳이요.', '문을 여닫던 흔적이 남은 자리요.']),
  (135, '소풍 약속 날 하늘이 흐리다면 상대에게 어떤 좋은 점을 귀띔할까요?', array['그늘을 찾아다니지 않아도 돼요.', '사진에서 꽃 색이 더 또렷해져요.', '구름 모양에 이름 붙이기 좋아요.']),
  (144, '“여기 같이 내려봐요” 하고 여행 상대를 부를 만한 정류장 이름은요?', array['끝에 나루터가 붙은 곳이요.', '달맞이처럼 밤 풍경이 궁금한 이름이요.', '오래된 나무 이름이 들어간 곳이요.']),
  (150, '섬에서 돌아오는 배까지 두 시간, 두 사람에게 딱 맞는 일정은요?', array['선착장이 보이는 언덕까지 걸어요.', '바닷바람을 막아 주는 돌담 옆에 앉아요.', '부표가 흔들리는 걸 보며 쉬어요.']),
  (152, '어떤 자연의 변화를 보면 좋아하는 사람에게 나들이 날짜를 잡자고 할까요?', array['나무 끝에 연둣빛이 돌 때요.', '첫 서리가 잔디를 하얗게 덮을 때요.', '한낮에도 땅 그림자가 길어질 때요.']),
  (161, '낮잠 자기 좋은 피크닉 장소를 귀로 고른다면 어떤 소리가 정답일까요?', array['마른 갈대가 부딪히는 소리요.', '멀리 배 한 척 지나가는 소리요.', '잎사귀 끝에서 빗물이 떨어지는 소리요.']),
  (166, '여행 중 각자 한 가지 색을 기억하기로 했다면, 내 색을 정할 장면은요?', array['오래된 우체통의 선명한 빨강이요.', '새벽 안개 사이로 보인 푸른 지붕이요.', '해 질 때 돌담에 남은 살구색이요.']),
  (170, '온실 데이트에서 상대에게 “이 식물은 꼭 봐야 해요” 하고 싶은 건요?', array['잎이 우산보다 큰 식물이요.', '둥글둥글 모여 있는 선인장이요.', '향을 맡으면 이름이 떠오르는 허브요.']),
  (179, '눈이 쌓인 날 신나게 놀자는 상대와 공터에서 가장 먼저 해 볼 건요?', array['발자국으로 커다란 별을 그려요.', '장갑 크기만 한 눈사람을 만들어요.', '아무도 밟지 않은 눈 소리를 들어요.']),
