  (189, '첫 산책길에 돌계단과 흙길이 나란하다면 상대에게 어디를 권할까요?', array['돌계단에 남은 닳은 자국을 보고 싶어요.', '이야기하기 좋은 흙길로 갈래요.', '올라갈 땐 계단, 내려올 땐 흙길이요.']),
  (195, '낮 데이트가 너무 좋았다면 어떤 풍경을 핑계로 저녁 약속도 잡을까요?', array['불이 켜질 것 같은 다리 난간이요.', '연못에 비칠 나무 그림자가 궁금해요.', '낮에 본 달 모양 조형물이 생각나요.']),
  (204, '강 건너로 데이트를 이어간다면 다리를 걸을까요, 나룻배를 탈까요?', array['중간에서 오래 멈출 수 있는 다리요.', '물 가까이 풍경을 보는 나룻배요.', '갈 때 배 타고 걸어서 돌아올래요.']),
  (206, '전통시장 데이트에서 아무것도 사지 않고 즐길 수 있는 구경거리는요?', array['손글씨로 쓴 옛 간판이요.', '색깔별로 가지런히 늘어선 바구니요.', '가게마다 다른 천막 색을 둘러봐요.']),
  (215, '둘이서 산책 이름을 하나 짓는다면 어떤 코스가 탄생할까요?', array['고양이를 만나면 멈추는 길이요.', '그늘만 골라 가는 여름길이요.', '모퉁이마다 번갈아 방향 정하는 길이요.']),
  (222, '여행을 못 간 상대에게, 사진 대신 어떤 감각으로 그곳을 설명해 줄까요?', array['배에서 내린 뒤에도 살짝 흔들리는 느낌이요.', '자갈 해변이 발밑에서 구르던 감촉이요.', '숲으로 들어섰을 때의 서늘한 공기요.']),
  (228, '둘이서 등대까지 걸어 도착했다면 어떤 마무리가 기억에 남을까요?', array['바다와 하늘의 경계선을 한참 봐요.', '등대 그늘에서 물 한 모금 마셔요.', '지나온 길이 얼마나 길었나 돌아봐요.']),
  (232, '밖에 나가기 싫어하던 사람에게 비 갠 길의 어떤 장면을 보여주고 싶나요?', array['잎 위에 모인 물방울이요.', '구름 틈새의 유난히 파란 하늘이요.', '반짝거리는 보도블록이요.']),
  (238, '전차로 시내를 구경하는 데이트라면 어느 자리를 상대에게 권할까요?', array['선로가 굽는 게 보이는 맨 앞자리요.', '창을 조금 열 수 있는 자리요.', '마주 보고 얘기할 수 있는 두 자리요.']),
  (241, '등산이 낯선 상대도 함께 즐길 수 있는 산 나들이를 짜 본다면요?', array['계곡 옆 너럭바위에서 쉬는 날이요.', '수목 안내판을 따라 한 바퀴 도는 날이요.', '첫 전망대에서 천천히 내려오는 날이요.']),
  (247, '함께 강변을 걷다 다리 밑에서 들리는 소리 중 좋아하는 건요?', array['발소리가 한 번 더 울리는 소리요.', '다리에 부딪힌 물결이 돌아오는 소리요.', '다리 위 자전거가 가볍게 지나가는 소리요.']),
  (254, '첫 기차 데이트에서 서로의 말에 귀 기울이기 좋은 이동 시간은요?', array['터널 몇 개 지나니 벌써 내릴 정도요.', '들판에서 산으로 풍경이 바뀔 만큼요.', '노을이 다 지는 걸 볼 수 있을 만큼요.']),
