  (282, '맑은 계곡에서 상대에게 나만의 보물찾기를 제안한다면 무엇을 찾을까요?', array['유리처럼 닳은 작은 돌이요.', '바위 사이에 생기는 소용돌이요.', '물속에 흔들리는 잎 그림자요.']),
  (287, '처음 만난 사람과 동네 축제에 간다면 어느 구경부터 시작할까요?', array['누구나 들어가도 되는 작은 춤판이요.', '동네 사람들이 만든 사진 전시요.', '손으로 짠 바구니를 보여 주는 자리요.']),
  (292, '데이트에서 본 예쁜 낙엽을 가져오지 않고 둘의 기억에 남기는 방법은요?', array['떨어진 그대로 사진 한 장만 찍어요.', '색이 닮은 물건을 서로 말해 봐요.', '잎맥을 눈으로 따라간 뒤 놓아줘요.']),
