  (305, '멀리 못 가는 상대에게 여행 기분을 선물할 방법이 있다면요?', array['평소와 반대 방향 열차에 올라요.', '종이 지도를 한 장 펼쳐요.', '보온병을 챙기고 일회용 카메라를 들어요.']),
  (310, '해변 산책 데이트, 도로와 모래길 중 어디부터 걷고 싶은지 말해 볼까요?', array['발 빠짐 없는 도로로 쭉 걸어요.', '힘들어도 파도 가까운 모래길이요.', '돌아갈 힘을 남기려고 반씩 걸어요.']),
  (317, '둘이 누워 보는 커다란 구름, 어떤 별명을 붙여 상대를 웃겨 볼까요?', array['앞장서서 달리는 양 떼요.', '뒤집힌 아이스크림 트럭이요.', '하늘에 널어 둔 겨울 이불이요.']),
  (321, '나보다 길눈이 밝은 상대가 지름길을 발견하면 어떻게 반응할까요?', array['어디로 나오는지 함께 확인해 봐요.', '길 이름이 생기면 그 친구 이름을 붙여요.', '돌아올 때 길잡이를 맡아 달라고 해요.']),
  (329, '전망 좋은 데이트 장소에서 내가 제일 먼저 알려주고 싶은 발견은요?', array['멀어 보인 두 광장이 사실 붙어 있어요.', '골목이 강을 따라서 휘어 있어요.', '지붕 색이 구역마다 조금씩 달라요.']),
  (335, '둘이 산책할 때 탁 트인 들길과 아늑한 숲길 중 어디를 권하고 싶나요?', array['발소리가 잘 들리는 숲길이요.', '멀리까지 보이는 들길을 걸을래요.', '갈 때는 숲길, 올 때는 들길이요.']),
  (341, '휴양지에서 상대의 제안이 들어올 수 있도록 비워 둘 일정은요?', array['마지막 날 오후에 갈 곳이요.', '아침에 어느 방향으로 걸을지요.', '해 질 무렵 잠시 앉을 자리요.']),
  (347, '첫 도보 데이트에 놀이 같은 규칙을 하나 보탠다면요?', array['파란 대문을 보면 오른쪽으로 가요.', '둥근 창문을 발견하면 서로 알려 줘요.', '모퉁이 세 개마다 길잡이를 바꿔요.']),
  (352, '“너 생각나서 찍었어” 하고 보낼 만한 뜻밖의 계절 풍경은요?', array['겨울 가지에 마지막 단풍잎 한 장이요.', '봄볕 속 담벼락 밑의 작은 눈더미요.', '늦가을에도 한 송이 남은 들꽃이요.']),
  (360, '같이 걷던 강에 둘만 아는 별명을 붙인다면 어떤 특징을 딸까요?', array['흐름이 느린 곳은 졸음강이요.', '돌을 만나 웃는 소리 나는 재잘강이요.', '저녁마다 금빛이 되는 노을강이요.']),
  (363, '공원 공연을 보는 데이트가 편하려면 두 사람은 어디쯤 서야 할까요?', array['박수 소리가 잘 닿는 앞쪽이요.', '사람들 표정도 보이는 옆자리요.', '잔디에 앉아 느긋하게 듣는 뒤쪽이요.']),
  (370, '나들이 중 휴대폰이 잠시 꺼지면 상대와 무얼 더 자세히 보게 될까요?', array['길모퉁이 표지판의 작은 글씨요.', '같이 걷는 사람이 자주 웃는 순간이요.', '눈으로 봐야만 느껴지는 하늘빛이요.']),
  (376, '식물을 좋아하는 사람에게 수목원을 안내한다면 어떤 나무 앞에서 시작할까요?', array['껍질 색이 얼룩덜룩한 나무요.', '잎에서 달콤한 향이 나는 나무요.', '두 사람이 겨우 안을 만큼 굵은 나무요.']),
  (383, '첫 여행의 탑승권을 모아 둔다면 어느 부분에 밑줄을 쳐 놓을까요?', array['잊기 쉬운 첫차의 출발 시각이요.', '나란히 붙은 좌석 번호 두 개요.', '처음 가 본 항구의 이름이요.']),
  (389, '한옥 마루에 나란히 앉으면 밖에서 어떤 게 보였으면 하나요?', array['담 너머 삐죽 나온 감나무요.', '대문 사이로 보이는 조용한 골목이요.', '밤새 빗물을 모은 작은 장독이요.']),
  (395, '두 사람 모두 무리 없이 즐길 자전거 데이트 코스를 고른다면요?', array['길게 뻗은 강변의 평지요.', '과수원 사이 완만한 흙길이요.', '해안선이 휘어지는 구간이요.']),
  (399, '북적이는 명소에서 같이 온 사람 덕분에 기분 좋아지는 순간은 언제일까요?', array['사람들 사이에서 제가 좋아할 자리를 찾아줘요.', '사람이 몰릴 때 그늘 쪽으로 비켜줘요.', '혼자라면 놓쳤을 풍경을 가리켜줘요.']),
  (405, '나들이에서 서로 다른 곳에 가고 싶다면 어떻게 정할까요?', array['한 곳씩 골라 순서만 정해요.', '두 곳 사이에서 재밌는 길을 찾아요.', '오늘 양보한 사람에게 다음 선택권을 줘요.']),
  (409, '처음 보는 꽃 앞에 쪼그려 앉은 상대와 이름을 알아낼 방법은요?', array['모양을 보고 엉뚱한 별명을 지어요.', '잎과 꽃잎을 사진에 같이 담아 찾아봐요.', '옆에 있는 식물 이름표부터 읽어요.']),
  (416, '함께 떠나는 밤 기차 여행, 잠이 안 올 때 제안하고 싶은 일은요?', array['간이역마다 다른 불빛을 봐요.', '식당칸이 있다면 끝까지 걸어가요.', '마주 앉아 낮게 이야기하고 싶어요.']),
  (422, '햇볕을 피해 상대와 잠깐 쉬고 싶을 때 즐겨 찾는 그늘은요?', array['햇살이 점처럼 새는 등나무 그늘이요.', '바닥까지 서늘한 돌 아치 아래요.', '바람 잘 통하는 커다란 천막이요.']),
  (427, '혼자서는 그냥 지나쳤을 텐데 둘이어서 들어가 볼 곳은요?', array['손님이 심사위원이 되는 작은 꽃 전시요.', '둘이 타야 가는 호수의 페달 보트요.', '혼자 들긴 쑥스러운 옛날 사진관이요.']),
  (434, '누군가에게 서두르지 말고 같이 숨 좀 돌리자고 하고 싶은 풍경은요?', array['숲이 끝나고 갑자기 바다가 열릴 때요.', '비 개인 돌담길에 흙냄새가 날 때요.', '이른 서리가 억새를 감싼 들이요.']),
  (442, '안내소에서 데이트를 더 재미있게 해 줄 물건 한 가지를 빌린다면요?', array['옛 거리 사진이 든 작은 앨범이요.', '새소리가 녹음된 해설 기기요.', '어디든 앉을 수 있는 접이식 의자요.']),
  (445, '추위를 많이 타는 상대와의 짧은 외출을 기분 좋게 마치는 방법은요?', array['마지막에 볕 드는 유리 온실에 들러요.', '따뜻한 물병을 서로 손에 쥐여 줘요.', '따끈한 국물이 기다리는 곳으로 걸어요.']),
  (454, '데이트 중 다리 하나에 둘만의 이름을 붙인다면 뭐가 어울릴까요?', array['바람을 오래 맞는 바람빗다리요.', '서로 만나기 좋은 절반다리요.', '물에 고운 빛을 드리우는 붓다리요.']),
  (459, '피크닉에 먼저 도착해 돗자리를 편다면 상대를 위해 뭘 살펴볼까요?', array['개미 길 한가운데는 아닌지 봐요.', '뒤로 누워도 햇볕이 눈부시지 않은지요.', '앉은 자리에서 수평선이 보이는지요.']),
  (467, '상대가 풍경을 가리키며 감탄하는데 눈에 잘 안 들어온다면요?', array['그 사람이 보는 높이에 맞춰 봐요.', '딱 한 단어로 힌트를 달라고 해요.', '어디가 좋았는지 듣는 걸 즐겨요.']),
  (473, '첫 데이트 장소를 다시 찾는 날, 처음과 다르게 해 보고 싶은 일은요?', array['처음과 반대 방향으로 한 바퀴 돌아요.', '해 뜰 때 문을 여는지 보러 가요.', '전에 놓친 안내 해설을 들어 봐요.']),
  (476, '갈대밭에 서서 보고 싶은 사람에게 음성 메시지를 남긴다면 뭐라고 할까요?', array['바람이 불면 땅 위에 파도가 생겨요.', '은빛 물고기가 우르르 몰려오는 것 같아요.', '여기 오면 바람의 발자국이 보여요.']),
  (482, '물 위 산책로에서 보통 길과 다른 점을 찾아 서로 알려준다면요?', array['발아래서도 하늘이 보여요.', '살짝 출렁일 때 보폭이 작아져요.', '새를 눈높이에서 만날 때가 있어요.']),
  (491, '날씨 구경을 좋아하는 사람과 유리창 너머로 오래 바라보고 싶은 건요?', array['붉은 석양을 가르는 소나기요.', '차곡차곡 쌓이는 함박눈이요.', '안개가 걷히며 산이 나타나는 아침이요.']),
  (496, '캠핑이 처음인 상대와 떠난다면 내가 맡아 주고 싶은 역할은요?', array['바람 덜 부는 텐트 자리를 골라요.', '밤에 볼 별자리 지도를 챙겨요.', '해가 지기 전에 의자부터 꺼내요.']),
  (499, '시골역에서 기다리는 시간이 길어질 때 상대와 함께 찾아보고 싶은 건요?', array['출입문 옆에 남은 옛 키 재기 눈금이요.', '낮잠 자는 역장 고양이요.', '벽에 쓰인 오래된 손글씨 시간표요.']),
  (509, '한참 오르막을 걸은 두 사람이 서로에게 건네면 좋을 말은요?', array['잠깐 멈춰서 뒤도 봐요.', '아까 시작한 곳이 벌써 저 아래예요.', '남은 길은 천천히 같이 가요.']),
  (511, '풀꽃 앞에 멈춰 선 모습을 봤을 때 상대가 알아줬으면 하는 내 취향은요?', array['이름 모르는 건 꼭 찾아보는 편이에요.', '작은 것을 오래 보는 게 편해요.', '사진 한 장보다는 잠깐 쪼그려 앉는 걸 좋아해요.']),
  (521, '오래 걷기 힘든 상대에게 여행 기분이 나는 데이트를 제안한다면요?', array['창가 자리에 앉아 유람선을 타요.', '시내 순환버스를 한 바퀴 타요.', '커다란 지도를 펴고 다음 길을 그려요.']),
  (524, '광장에서 느긋한 데이트를 한다면 두 사람의 눈길이 머물 곳은요?', array['분수 물줄기가 변하는 순서요.', '비둘기들이 자꾸 길을 비키는 모습이요.', '해시계 그림자가 움직이는 속도요.']),
  (531, '여행 가방을 열었을 때 어떤 향이 남아 있으면 동행도 웃을까요?', array['숲에서 묻어 온 솔잎 향이요.', '햇볕에 말린 수건 냄새요.', '섬에서 산 귤이 남긴 향이요.']),
  (535, '둘만 과거로 여행할 수 있다면 어느 장소의 옛 모습을 함께 보고 싶나요?', array['물건을 실은 배로 붐비던 나루터요.', '첫 열차가 들어오던 작은 역이요.', '나무들이 어린 묘목이었던 숲길이요.']),
  (541, '여행을 같이 가기로 했을 때 출발 전 나누고 싶은 약속은요?', array['피곤하면 눈치 보지 말고 쉬자고 해요.', '한 사람당 가고 싶은 곳 하나는 가요.', '길을 헤매도 남 탓은 하지 말아요.']),
  (550, '둘이 이른 아침에 만났다면 첫 볕이 드는 풍경을 어디서 볼까요?', array['높은 건물 유리창부터 볼래요.', '동쪽 산등성이를 따라가 봐요.', '물에 닿는 첫 햇빛을 찾아요.']),
  (556, '자갈 해변에서 둘이 무언가를 줍지 않아도 즐길 수 있는 놀이는요?', array['제일 납작한 돌을 눈으로만 골라요.', '파도가 남긴 색색의 돌을 세어요.', '누가 먼저 하트 모양을 찾나 살펴요.']),
  (561, '케이블카 데이트에서 상대한테 “지금 봐요!” 하고 싶은 순간은요?', array['바닥이 서서히 멀어지기 시작할 때요.', '기둥을 지나며 한 번 살짝 흔들릴 때요.', '숲 너머 호수가 한눈에 들어올 때요.']),
  (568, '요즘 쉴 틈이 없던 상대를 위해 여행 일정에서 가장 먼저 덜어낼 건요?', array['아침 일찍 움직이는 일정을 빼요.', '한 번밖에 못 간다는 마음을 내려놔요.', '멀리 떨어진 명소 하나를 덜어내요.']),
  (572, '같이 걸을 동네의 옛 지도 한 장을 받는다면 무엇을 찾아갈까요?', array['길 아래 숨어 버린 예전 개천이요.', '이름은 달라져도 그대로 남은 광장이요.', '백 년 전에도 제자리를 지킨 큰 나무요.']),
  (577, '여행이 끝난 뒤 동행에게 보내고 싶은 짧은 문장은요?', array['길 잃은 시간이 제일 웃겼어요.', '다음번엔 제가 창가 자리 양보할게요.', '나란히 아무 말 없이 걸어서 좋았어요.']),
  (586, '도심 정원을 소개해 준다면 어떤 모습을 보고 함께 미소 짓고 싶나요?', array['점심 산책 나온 둘이 친구를 만난 모습이요.', '아이들이 나비를 보고 동시에 멈추는 모습이요.', '두 어르신이 꽃 이름을 맞혀 보는 모습이요.']),
  (592, '나중에 둘레길 데이트를 청하려고 먼저 걸어본다면 뭘 확인할까요?', array['갈림길마다 화살표가 잘 보이는지요.', '쉬어 갈 의자 사이가 너무 멀지 않은지요.', '돌아오는 길도 찾기 쉬운지요.']),
  (597, '가벼운 데이트 여행, 빈 주머니 하나를 남겨 뒀다가 무엇을 넣을까요?', array['가는 곳마다 찍은 도장 수첩이요.', '바람에 날아갈까 접어 둔 승선권이요.', '손을 비우고 풍경만 담고 올래요.']),
  (602, '연못 데이트 도중 누구와 눈이 마주치면 서로 눈짓을 주고받게 될까요?', array['일광욕하다 고개 든 거북이요.', '돌 사이에 웅크린 작은 개구리요.', '물가에서 깃을 고르던 왜가리요.']),
  (607, '둘이 묵는 곳의 방명록을 펼쳐 어떤 글을 상대한테 읽어주고 싶나요?', array['서쪽 창으로 달이 들어온다는 귀띔이요.', '어제 본 새를 서툴게 그려 놓은 글이요.', '여기서 잘 쉬고 간다는 짧은 인사요.']),
  (614, '함께 걷다가 말이 많아지는 길과 조용해지는 길은 어떻게 다른가요?', array['숲에서는 새소리 들으려고 조용해져요.', '간판이 재밌는 거리에선 말이 많아져요.', '발밑이 고르면 서로 얼굴을 더 봐요.']),
  (620, '둘이 좋아하는 쉼터를 꾸밀 수 있다면 흔한 방명록 대신 뭘 놓을까요?', array['오늘 보인 색을 칠하는 작은 색연필이요.', '지나가는 바람을 보는 종이 바람개비요.', '저 멀리 뭘 봤는지 적는 작은 지도요.']),
  (626, '여행 해설가에게 질문할 기회가 오면 동행도 흥미로워할 어떤 걸 물을까요?', array['여기서 가장 많이 달라진 곳은 어딘가요?', '이름을 잘못 부르는 장소가 있나요?', '이 풍경이 예뻐지는 시간은 언제예요?']),
  (631, '버스 여행 중 잠을 깨우더라도 같이 보고 싶은 장면은요?', array['터널 끝에서 갑자기 보이는 바다요.', '산기슭을 길게 덮은 운해요.', '창 너머로 가까이 뜬 무지개요.']),
  (639, '물이 빠진 바닷가 데이트에서 발견하는 즉시 상대를 부르고 싶은 것은요?', array['물이 남긴 모래 무늬가 궁금해요.', '작은 게가 숨어드는 구멍이요.', '물에 잠겼던 바위의 색이 궁금해요.']),
  (645, '동행이 쉬자고 했을 때 마침 의자가 없다면 어디가 좋을까요?', array['그늘 아래 평평한 돌담 턱이요.', '계단 끝에서 통행을 막지 않는 자리요.', '접이식 방석을 펴기 좋은 잔디요.']),
  (651, '함께 떠날 날짜를 정할 때 더 양보하기 어려운 건 날씨일까요, 풍경일까요?', array['선선하게 오래 걸을 수 있는 날씨요.', '일 년에 잠깐만 보는 들꽃 풍경이요.', '비 오는 바다가 목적이면 둘 다 맞아요.']),
  (658, '긴 이동에 지친 상대에게 여행의 좋은 장면을 하나 선물한다면요?', array['보름달이 뜬 쪽의 창가를 내줘요.', '목베개를 건네 잠시 눈 붙이게 해줘요.', '바다가 보이는 순간 조용히 귀띔해요.']),
  (661, '데이트 코스를 물길 따라 정한다면 어디쯤에서 둘이 쉬고 싶나요?', array['작은 개울이 큰 강을 만나는 곳까지요.', '물소리가 들리는 첫 다리까지만요.', '물길 따라 자란 버드나무가 끝날 때까지요.']),
  (671, '둘이 천천히 맞추는 여행의 첫 박자는 어떤 순간일까요?', array['신발 끈을 묶는 동안 기다려 줄 때요.', '가고 싶은 곳 하나씩 꺼내 볼 때요.', '환승길에 말없이 나란히 속도를 낼 때요.']),
  (676, '바닷가 데이트에서 종이접기로 상대에게 작은 선물을 한다면 뭘 접을까요?', array['갈매기를 접어 나란히 세워 두고 싶어요.', '작은 배를 접어 손바닥에 올릴래요.', '봉투를 접어 오늘의 편지를 담을래요.']),
  (684, '함께 떠난 나들이에 빈 수첩 하나, 나부터 어느 쪽을 채워 볼까요?', array['들린 소리를 흉내 낸 단어요.', '길에서 본 대문 모양 서너 개요.', '돌아갈 때 써먹을 서툰 약도요.']),
  (687, '함께 산책한 날을 달력에 글자 하나로 표시한다면 뭐가 좋을까요?', array['볕이 따뜻한 날이라 볕이요.', '돌담을 오래 본 날이라 돌이요.', '같이 건넌 다리가 좋아서 물이요.']),
  (693, '둘이 먼 길을 왔는데 구름에 전망이 가렸다면 어떻게 마음을 맞출까요?', array['가까운 바위와 이끼를 자세히 봐요.', '따뜻한 차 한 잔 하며 잠깐 기다려요.', '안개 속 모습도 그날 풍경으로 간직해요.']),
  (697, '둘이 눈으로만 모으는 여행 기념품을 정한다면 어떤 것일까요?', array['가게 앞의 개성 있는 입간판이요.', '고개를 들어야 보이는 풍향계요.', '바닥에 새겨진 오래된 연도요.']),
  (707, '언덕길을 힘들게 오르는 상대에게 이 마을의 어떤 매력을 말해 주고 싶나요?', array['층층이 포개진 지붕의 색이요.', '잠깐 멈춰 쉬며 본 탁 트인 하늘이요.', '내려올 때 달라 보이는 골목 모양이요.']),
  (713, '새로운 곳이 낯설다는 상대에게 공감해 줄 때 내 경험을 하나 꺼낸다면요?', array['저도 낯설었는데 그림책에서 본 색이 반갑더라고요.', '갈대 소리를 들으니 긴장이 조금 풀렸어요.', '길을 비켜준 사람의 미소가 위안이 됐어요.']),
  (717, '처음인 사람과 평평한 길을 오래 걸을 때 어떤 리듬으로 발을 맞출까요?', array['옆 사람 발소리에 맞춰 걸어요.', '파도가 밀려오는 간격에 맞춰요.', '속으로 좋아하는 노래 후렴을 불러요.']),
  (723, '헤어지기 아쉬운 산책길 끝자락, 상대에게 마지막으로 뭘 함께하자고 할까요?', array['몸을 한 바퀴 돌려 사방을 바라봐요.', '그날의 공기를 한껏 들이마셔요.', '다음에는 어디로 걸을지 서로 골라요.']),
  (729, '여행이 잘 맞는다는 걸 목적지 말고 어떤 순간에 느끼나요?', array['둘 다 같은 벤치에서 더 쉬고 싶을 때요.', '예정에 없는 정거장에서 같이 내릴 때요.', '풍경이 좋단 말에 동시에 고개 들 때요.']);
